from h import *
A = dict(id="A", levels=L1, kind="Web page", source="Marram Bay Town Council website", title="Welcome to Marram Bay", body=[
 {"p": "Marram Bay is a friendly seaside town with a busy harbour and a lively market."},
 {"p": "**Population:** about 9,000"},
 {"p": "**Distance to Northcaster:** 40 miles"},
 {"p": "**Trains to Northcaster:** every hour"},
 {"p": "**Schools:** two primary schools and one secondary school"},
 {"p": "We hope you will visit us soon, and perhaps even stay."},
 {"p": "Our long, sandy beach is open all year, and there is a weekly market on Saturdays. Many families live here because homes cost less than in the city, and the countryside is close by."}])
B = dict(id="B", levels=L1, kind="Magazine article", source="Home & Away magazine", title="Should you move to the coast?", body=[
 {"p": "Every year, thousands of people leave the cities for life by the sea. Some want cheaper homes, some want fresh air, and some simply want a change. But is the seaside really the dream it seems?"},
 {"h": "The good points"},
 {"p": "Property prices in small seaside towns are usually lower than in big cities, so your money often goes further. Estate agent Karen Webb says, \"You get more for your money by the sea.\" There is plenty to do, too, with cafés, shops, boat trips and a market in many towns. Life can also feel calmer, and the beach is often only a short walk from home. Many people also say that the air feels cleaner and that their children have more space to play outdoors."},
 {"h": "The not-so-good points"},
 {"p": "Many seaside towns have far more visitors in summer than in winter, so a lot of the jobs are seasonal. A café or hotel may employ extra staff from May to September, but then lay them off when the weather turns cold. People who work in cities often have to commute by train, which can be expensive. Some small towns have fewer services too, such as hospitals and large shops, and buses to nearby towns can be infrequent, particularly in the evenings."},
 {"h": "What should you check first?"},
 {"p": "Before you move, visit the town in the middle of winter, not just on a sunny weekend in August. Check how often the trains run, how far away the nearest hospital is, and whether there are good schools nearby. Talk to people who already live there, because they will give you an honest view."},
 {"p": "Living by the sea is a wonderful experience, and nothing beats waking up to the sound of the waves. With careful planning, it could be the best decision you ever make."}])
C = dict(id="C", levels=L1, kind="Blog post", source="Our Seaside Life blog", title="One year since we left the city", body=[
 {"p": "A year ago, we swapped a tiny flat in Northcaster for a little house in Marram Bay. Everyone said we were mad, but we've never looked back and we have never been happier."},
 {"p": "The house cost far less than our flat would have sold for, and we now have a garden! The beach is five minutes away, and I swim most mornings, even in the cold. I'd never have done that in the city. The winters are wild but beautiful, and we have met more neighbours in a year than in five years in Northcaster."},
 {"p": "But it hasn't all been easy. I work at a café on the harbour, and in January there were hardly any customers, so I only had two shifts a week. My partner commutes to Northcaster by train, which costs a fortune, and the last train home is far too early."},
 {"p": "My advice if you're thinking of moving:"},
 {"ul": ["Visit in winter, not just in summer.", "Work out the cost of the train before you buy a house.", "Be ready to find a second job for the quiet months."]},
 {"p": "Would we move back? No way! But we're a lot wiser than we were."}])

